// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        // Ensure arrays have the same length and non-empty
        vm.assume(_tos.length == v.length);
        vm.assume(_tos.length > 0);
        // Ensure no arithmetic overflow in mul_uint256 for any element
        for (uint i = 0; i < v.length; i++) {
            vm.assume(v[i] <= type(uint256).max / 1000000000000000000);
        }

        // Set the required sender
        address requiredSender = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(requiredSender);

        // capture return value; transfer should not revert for admissible inputs
        bool success;
        bool result;
        try c.transfer(_tos, v) returns (bool ret) {
            success = true;
            result = ret;
        } catch {
            success = false;
        }

        // If transfer succeeded, result must be true (reference invariant)
        // Bug: mutant returns false
        assertTrue(!success || result);
    }
}

