// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        // keep inputs admissible: equal-length non-empty arrays, sender is the required address
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        // constrain v[i] to avoid overflow in mul_uint256 (a * 1e18)
        uint256 maxV = type(uint256).max / 1e18;
        for (uint i = 0; i < v.length; i++) {
            v[i] = bound(v[i], 0, maxV);
        }
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool success;
        try c.transfer(_tos, v) returns (bool ret) {
            success = true;
            // the general rule: on every non-reverting call triggered by the fuzzed input,
            // the return value must be true.
            assertTrue(ret);
        } catch {
            success = false;
        }
        // if it did not revert, we have already asserted that ret == true.
        // The bug breaks this rule because it returns false even when the call does not revert.
    }
}
